    /**
     * Method to retrieve the Payout via PayoutFetchOneSummary
     * @param 	summary PayoutFetchOneSummary 
     * @return 	PayoutFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Payout getPayout( PayoutFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PayoutFetchOneSummary arg cannot be null" );
    	
    	Payout entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Payout
        	// --------------------------------------
        	CompletableFuture<Payout> futureEntity = queryGateway.query(new FindPayoutQuery( new LoadPayoutFilter( summary.getPayoutId() ) ), ResponseTypes.instanceOf(Payout.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Payout with id " + summary.getPayoutId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


