    /**
     * assign Merchant on Payout
     * @param		command AssignMerchantToPayoutCommand	
     * @exception	ProcessingException
     */     
	public void assignMerchant( AssignMerchantToPayoutCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getPayoutId() );
		
		MerchantService childDelegate 	= MerchantService.getMerchantInstance();
		PayoutService parentDelegate = PayoutService.getPayoutInstance();			
		UUID childId = command.getAssignment().getMerchantId();
		Merchant child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Merchant using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

